import React from "react";
import { Link } from "react-router-dom";
import babyImg from "../assets/117.png";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff1f8, #e6faff, #fff9e6)",
        padding: "60px 20px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {/* HERO SECTION */}
      <div style={{
      textAlign: "center",
      padding: "80px 20px",
      background: "linear-gradient(to right, #fff0f5, #f0f9ff)"
    }}>
      
      <h1 style={{ fontSize: "48px", color: "#d63384" }}>
        Nanhe Farishte <br /> Kiran Knits
      </h1>

      <p style={{ fontSize: "20px", color: "#555" }}>
        Har bunai mein maa ka pyaar 💕
      </p>

      <img 
        src={babyImg} 
        alt="Cute Baby"
        style={{
          width: "300px",
          marginTop: "30px",
          borderRadius: "25px",
          boxShadow: "0 15px 40px rgba(0,0,0,0.2)"
        }}
      />

      <br />

      <button style={{
        marginTop: "30px",
        padding: "15px 35px",
        background: "#ff85a2",
        border: "none",
        borderRadius: "30px",
        color: "white",
        fontSize: "16px"
      }}>
        Shop Now
      </button>
    </div>
  );

      {/* CATEGORY SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            fontSize: "34px",
            marginBottom: "60px",
            color: "#444",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "50px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard emoji="🧥" title="Sweaters" link="/products?category=Sweater" />
          <CategoryCard emoji="🧦" title="Socks" link="/products?category=Socks" />
          <CategoryCard emoji="🧢" title="Caps" link="/products?category=Cap" />
        </div>
      </div>
    </div>
  );
};

const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "70px 40px",
          borderRadius: "30px",
          width: "240px",
          fontSize: "24px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
          transition: "0.3s ease",
          cursor: "pointer",
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform =
            "translateY(-15px) scale(1.05)";
          e.currentTarget.style.background =
            "linear-gradient(135deg, #ffe0f0, #e0f7ff)";
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform =
            "translateY(0) scale(1)";
          e.currentTarget.style.background = "white";
        }}
      >
        <div style={{ fontSize: "45px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

export default Home;
